Lemma keepK_stepR : forall C (K : word -> Prop) (s data nd : Z) (mprev N n : word -> option byte),
  (forall a : word, K a -> ~ scratch C s a /\ ~ (data <= bv_unsigned a < data + nd)%Z) ->
  (forall x : word, ~ (s - 96 <= bv_unsigned x < s - 88)%Z -> N x = mprev x) ->
  (c_top C - LSTK <= s - 96)%Z ->
  (forall a : word, ~ scratch C (s - 96) a -> ~ (data <= bv_unsigned a < data + nd)%Z -> n a = N a) ->
